// Pattern transforms ported from pattern_variants.lua (SPEC §5): builds variant k (0..3) of a category from the source.
#pragma once
#include "../core/types.h"
#include "key.h"
namespace lp {
struct Rng { uint32_t s; explicit Rng(uint32_t seed) : s(seed ? seed : 1) {} uint32_t next() { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return s; } int range(int lo, int hi) { return lo + (int)(next() % (uint32_t)(hi - lo + 1)); } float unit() { return (next() & 0xFFFFFF) / 16777216.0f; } };
// Builds variant into out. seed makes the result deterministic for a given source. Returns the variant's display name.
// Original (variant 0 of the tonal categories) is the source normalized (sorted, duplicates merged). Vocal variants
// 2 / 3 carry only their natural length (2 / 1 beats, SPEC §9.4); the engine streams the file (SPEC §9.3).
const char* buildVariant(Category c, const Pattern& source, int variant, uint32_t seed, const ProjectKey& key, Pattern& out);
// Same with the Percussion fold map computed at load and stored (SPEC §9.7): layer ordinals count per original
// pitch and the stored map keeps every voice stable when edits change the pitch counts. nullptr = map of `source`.
const char* buildVariant(Category c, const Pattern& source, int variant, uint32_t seed, const ProjectKey& key, Pattern& out,
                         const uint8_t foldMap[128]);
// Specific transforms (exposed for tests)
void cropPattern(const Pattern& src, uint16_t lengthTicks, Pattern& out);       // crop(), keeps first L ticks, loops at L
void beatLayer(const Pattern& src, int layer, Rng& rng, Pattern& out);           // 0 Kick, 1 Kick+Hats, 2 +Snare, 3 Full (+ one accent pitch 40..58 kept as is; the engine plays 40..58 on the open-hat slot, SPEC §9.6)
void percussionLayer(const Pattern& src, int layer, Pattern& out);               // Sparse/Light/Driving/Full
void foldPercussionVoices(Pattern& p);                                           // map pitches onto 36..39 (SPEC §6, §9.7) = percussionFoldMap + applyPercussionFold
void percussionFoldMap(const Pattern& src, uint8_t map[128]);                    // SPEC §9.7 voice map (four most frequent → 36..39 by count desc / pitch asc, rest 36 + (pitch & 3)); computed at load and stored
void applyPercussionFold(Pattern& p, const uint8_t map[128]);                    // apply a stored map in place (merges duplicates, sorts)
void chordVariation(const Pattern& src, Rng& rng, const ProjectKey& key, Pattern& out);
void leadVariation(const Pattern& src, Rng& rng, const ProjectKey& key, Pattern& out);
void mutatePattern(const Pattern& src, float strength, Rng& rng, const ProjectKey& key, Pattern& out);
void limitPolyphony(const Pattern& src, int voices, Pattern& out);
void generatedFx(const Pattern& src, uint16_t lengthTicks, Rng& rng, const ProjectKey& key, Pattern& out);
void snareRush(const Pattern& fullLayer, Pattern& out);                          // crop(Full, 1 beat) without pitch 36; snares on every 1/16 when none remain (SPEC §9.6)
// Acid generators (SPEC §9.17b): deterministic in (seed, key), written to a track's SOURCE so variants, set files and
// the editor work unchanged (variant 0 = the line). Both constrain every pitch to the key (ProjectKey::degreePitch /
// snap) and clamp it to 12..115.
// acidLine (Lead / Bass): 16 steps (1 bar) or 32 steps (2 bars) on the 1/16 grid, root-heavy with octave jumps,
// ≈ 30 % slides (the note runs to the next onset + 12 ticks so its note-off follows the next note-on → legato glide
// in the engine, SPEC §9.12 ordering), ≈ 20 % accents (velocity ≥ 100), 10..25 % rests, other notes 12 or 24 ticks.
// baseOctave is the root's MIDI octave (C3 = 48 convention of key.h): Bass 1 (A1 = 33), Lead 2 (A2 = 45).
void acidLine(uint32_t seed, const ProjectKey& key, Pattern& out, int baseOctave = 1);
// acidStabs (Chord / Pad): 2..3 note diatonic stabs (triad, m7 or sus voicings over the tonic, iv, bVI or bVII) on
// an offbeat rhythm (the 8th "and"s, a few offbeat 16ths), 24 or 36 ticks long, 1 or 2 bars; ≈ 20 % accents.
void acidStabs(uint32_t seed, const ProjectKey& key, Pattern& out, int baseOctave = 3);

// ---- Theory set generator (SPEC §9.24) ------------------------------------------------------------------------------
// One coherent set from ONE chord progression of the flash tables (theory_tables.hpp, generated by
// tools/make_theory_tables.py from the same tools/theory_data.py the Mac clip generator uses). theoryPlan() draws the plan
// from the generator's Rng — progression, voicing template, chord / bass / lead rhythm templates, styles, one melodic
// seed — and voices the progression for the Pad (3–4 voices, close or open per template, the inversion of every chord
// chosen for the least total voice movement inside 59..77). theoryBuild() then writes a melodic category's SOURCE pattern
// from the plan alone (pure, deterministic, no card): Pad = the voicings sustained per chord; Chord = the same voicings
// through a 16-step rhythm template as stabs / broken chords / plucks; Bass = root / fifth / octave / approach patterns
// from its own template bank, 38..59, one voice, ≈ 20 % slides (the note runs 12 ticks past the next onset: the engine's
// legato glide); Lead = a motif of chord tones + diatonic passing tones (scale-degree Markov walk, strong beats on chord
// tones) laid out A A' B A' (A A' on a 2-bar progression), 60..84, ≈ 20 % accents; Fx = hits on the chord changes.
// Every pitch class is in the natural minor of the key except the alterations a chord code allows (theoryAllowedPcs: the
// leading tone of V / vii°, the dorian sixth of IV); every pattern starts with an onset at tick 0 (the crop variants
// are never empty) and holds <= kMaxNotes notes. No heap, stack frames well under 1 KB.
struct TheoryPlan {                           // 52 B: the generator keeps one (its only RAM besides the flash tables)
  uint8_t prog = 0;                           // theory::kProgs index
  uint8_t nChords = 4;                        // 2 / 4 / 8 chords
  uint8_t chordSteps = 16;                    // 1/16 steps per chord: 8 (half a bar), 16 (a bar), 32 (two bars); nChords × chordSteps <= 64
  uint8_t root = 9;                           // key root the plan was voiced in
  uint8_t voicingTpl = 0;                     // theory::kVoicings index
  uint8_t chordRhythm = 0;                    // theory::kChordRhythms index
  uint8_t chordStyle = 0;                     // 0 stabs (every voice), 1 broken (full / upper voices alternating), 2 plucks (one voice per onset)
  uint8_t chordLow = 0;                       // the stabs an octave below the pad voicings (when that stays >= 36)
  uint8_t bassTpl = 0;                        // theory::kBassTpls index
  uint8_t bassGate = 0;                       // 0 staccato (12 ticks), 1 the step (24), 2 legato to the next onset
  uint8_t leadRhythmA = 0, leadRhythmB = 0;   // theory::kLeadRhythms indices of the motif (A, A') and of B
  uint8_t leadVar = 0;                        // theory::LeadVar: how A' varies A
  uint8_t leadGate = 0;                       // 0 stabs (24 ticks), 1 plucks (12), 2 legato (3/4 of the way to the next onset)
  uint8_t padStyle = 0;                       // 0 sustain, 1 swell (re-attacked at half the chord, softer), 2 pulse (quarter notes)
  uint8_t fxStyle = 0;                        // 0 a hit on every change, 1 hits + a riser under the last chord, 2 hits on the downbeat and the middle only
  uint32_t seed = 1;                          // the melodic draws (walk, accents, slides): one Rng per category from it
  uint8_t voicing[8][4] = {};                 // pad voicing per chord, low to high, 0 = no voice
};
static_assert(sizeof(TheoryPlan) == 52, "TheoryPlan is the theory generator's whole RAM state");
inline bool theoryCategory(Category c) { return c == Chord || c == Lead || c == Pad || c == Bass || c == Fx; }
constexpr int kTheoryPadLo = 59, kTheoryPadHi = 77;     // register bands (SPEC §9.24)
constexpr int kTheoryBassLo = 38, kTheoryBassHi = 59;
constexpr int kTheoryLeadLo = 60, kTheoryLeadHi = 84;
constexpr int kTheoryChordLo = 36, kTheoryChordHi = 79;
constexpr int kTheoryFxLo = 60, kTheoryFxHi = 84;
void theoryPlan(Rng& rng, int keyRoot, TheoryPlan& plan);             // draws every choice and voices the progression
void theoryBuild(const TheoryPlan& plan, Category c, Pattern& out);   // the category's source pattern (Chord / Lead / Pad / Bass / Fx; others: cleared)
int theoryProgName(const TheoryPlan& plan, char* out, int cap);        // "i-VI-III-VII" (ASCII numerals; "V", "IV", "viidim", "isus4"); returns the length
// Harmony helpers (also the tests' reference)
uint16_t theoryLengthTicks(const TheoryPlan& plan);                    // nChords × chordSteps × 24
int theoryChordAt(const TheoryPlan& plan, int tick);                   // chord index sounding at a tick of the pattern
uint8_t theoryChordCode(const TheoryPlan& plan, int chord);            // degree | alteration << 3 (theory_tables.hpp)
int theoryChordPcs(int root, uint8_t code, const uint8_t* stack, int n, uint8_t* pcs);   // pitch classes of the chord's diatonic stack with the alteration applied; returns the count (duplicates dropped)
uint16_t theoryAllowedPcs(int root, uint8_t code);                     // bit pc: the natural minor plus the chord's borrowed pitch classes
}
